-- walk-0, a synthetic world (REM-1191), as the sample's own tables. Generated by build/world.py: the rows below are
-- the world's items, tags, sittings and nearest lists, unchanged. A second load starts the schema again.
set role app_owner;
drop schema if exists walk_world cascade;
create schema walk_world;
create table walk_world.items (id uuid primary key, key text unique not null, kind text not null,
                               sitting text, pos int);
create table walk_world.tags (id uuid primary key, key text unique not null, n int not null);
create table walk_world.tagged (item uuid not null, tag uuid not null);
create table walk_world.next (a uuid not null, b uuid not null, sitting text not null, pos int not null);
create table walk_world.nearest (a uuid not null, b uuid not null, rank int not null);
create table walk_world.questions (id uuid primary key, key text unique not null, phrasing text not null);
create table walk_world.seeds (question uuid not null, item uuid not null, rank int not null);
